import { userProjectionToValue } from './user.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('userProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    tenant: { $ref: 'ref-tenant' },
    name: 'value-name',
    password: 'value-password',
    email: 'value-email',
    welcomeAt: 'value-welcomeAt',
    emailVerified: 'value-emailVerified',
    enabled: 'value-enabled',
    approvalStatus: 'value-approvalStatus',
    temporalPassword: 'value-temporalPassword',
    useSecondFactors: 'value-useSecondFactors',
    blockedUntil: 'value-blockedUntil',
    federatedProvider: 'value-federatedProvider',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(userProjectionToValue(null)).toBeNull();
    expect(userProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(userProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      tenant: () => ({ uid: 'ref-tenant' }),
      name: 'value-name',
      password: 'value-password',
      email: 'value-email',
      welcomeAt: 'value-welcomeAt',
      emailVerified: 'value-emailVerified',
      enabled: 'value-enabled',
      approvalStatus: 'value-approvalStatus',
      temporalPassword: 'value-temporalPassword',
      useSecondFactors: 'value-useSecondFactors',
      blockedUntil: 'value-blockedUntil',
      federatedProvider: 'value-federatedProvider',
      version: 'value-version',
    } as any;
    expect(userProjectionToValue(projection)).toEqual(value);
  });
});
